import json
import re
from datetime import datetime

_DAY = re.compile(r'\d{4}-\d{2}-\d{2}\Z')


def _parse_rows(text):
    try:
        rows = json.loads(text)
    except (ValueError, TypeError) as error:
        raise ValueError(f'malformed JSON: {error}') from error
    if not isinstance(rows, list):
        raise ValueError('expected a JSON array of rows')
    return rows


def _parse_day(value):
    if not isinstance(value, str) or not _DAY.match(value):
        raise ValueError('day must be a YYYY-MM-DD string')
    try:
        return datetime.strptime(value, '%Y-%m-%d').date()
    except ValueError as error:
        raise ValueError(f'invalid day: {error}') from error


def _parse_row(row):
    if not isinstance(row, dict):
        raise ValueError('each row must be a JSON object')

    tenant = row.get('tenant')
    if not isinstance(tenant, str) or not tenant:
        raise ValueError('tenant must be a nonempty string')

    amount_cents = row.get('amount_cents')
    if isinstance(amount_cents, bool) or not isinstance(amount_cents, int):
        raise ValueError('amount_cents must be an integer')

    day = _parse_day(row.get('day'))
    return amount_cents, day


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    days = []
    total_cents = 0
    for row in _parse_rows(text):
        amount_cents, day = _parse_row(row)
        total_cents += amount_cents
        days.append(day)

    return {
        'row_count': len(days),
        'total_cents': total_cents,
        'first_day': min(days).isoformat() if days else None,
        'last_day': max(days).isoformat() if days else None,
    }
